package com.example

/**
 * Question Bank for Applied & Elective Subjects:
 * ICT, Commerce, Health, Agriculture, English, and Electives (Civic, Music, Art, Dance, Drama).
 * Each subject provides 10 distinct sets of 10 unique, curriculum-accurate MCQs (100 distinct questions per subject).
 */
object QuizBankApplied {

  // -------------------------------------------------------------
  // ICT (තොරතුරු හා සන්නිවේදන තාක්ෂණය)
  // -------------------------------------------------------------
  fun getIctQuestion(grade: String, setIdx: Int, qIdx: Int, qNumber: Int, topic: String): QuizQuestion {
    return when (setIdx) {
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "පරිගණකයක මධ්‍යම සැකසුම් ඒකකය (CPU) තුළ අංකගණිත හා තර්ක මෙහෙයුම් සිදුකරන කොටස කුමක්ද?", listOf("ALU (Arithmetic Logic Unit)", "CU (Control Unit)", "RAM", "Register"), 0, "ALU මඟින් එකතු කිරීම්, අඩු කිරීම් සහ සංසන්දනාත්මක තර්ක ක්‍රියා සිදුකරයි.")
        2 -> QuizQuestion(qNumber, "පරිගණකය ක්‍රියාත්මක වන විට තාවකාලිකව දත්ත රඳවා ගන්නා ප්‍රධාන මතකය කුමක්ද?", listOf("RAM (Random Access Memory)", "ROM", "Hard Disk", "Flash Drive"), 0, "RAM යනු විදුලිය විසන්ධි වූ විට දත්ත මැකී යන තාවකාලික (Volatile) මතකයකි.")
        3 -> QuizQuestion(qNumber, "පරිගණකය පණගැන්වීමට (Booting) අවශ්‍ය මූලික උපදෙස් ස්ථිරව ගබඩා කර ඇත්තේ කුමන මතකයේද?", listOf("ROM (Read Only Memory)", "RAM", "Cache Memory", "Virtual Memory"), 0, "ROM මතකයේ BIOS / UEFI වැඩසටහන ස්ථිරව (Non-volatile) තැන්පත් කර ඇත.")
        4 -> QuizQuestion(qNumber, "පරිගණකයට දත්ත ඇතුළත් කරන ආදාන උපාංගයක් (Input Device) නොවන්නේ කුමක්ද?", listOf("යතුරුපුවරුව (Keyboard)", "මූසිකය (Mouse)", "මුද්‍රණ යන්ත්‍රය (Printer)", "ස්කෑනරය (Scanner)"), 2, "මුද්‍රණ යන්ත්‍රය (Printer) ප්‍රතිදාන (Output) උපාංගයක් වේ.")
        5 -> QuizQuestion(qNumber, "CPU එක සහ ප්‍රධාන මතකය (RAM) අතර වේගවත් දත්ත හුවමාරුවට යොදන අතිශය වේගවත් කුඩා මතකය කුමක්ද?", listOf("කෑෂ් මතකය (Cache Memory)", "ද්විතීයික මතකය", "DVD", "HDD"), 0, "කෑෂ් මතකය CPU එකෙහි කාර්යක්ෂමතාව ඉහළ නැංවීමට යොදාගනී.")
        6 -> QuizQuestion(qNumber, "චුම්භක තාක්ෂණය මත පදනම්ව විශාල දත්ත ධාරිතාවක් ගබඩා කරන ද්විතීයික ගබඩා උපාංගය කුමක්ද?", listOf("දෘඪ තැටිය (Hard Disk Drive - HDD)", "RAM", "ROM", "CPU"), 0, "HDD තුළ චුම්භක තැටි මත දත්ත ස්ථිරව ගබඩා කර තබා ගනී.")
        7 -> QuizQuestion(qNumber, "පරිගණකයක සියලුම උපාංග (CPU, RAM, Graphic Card) සවි කර එකිනෙක යා කරන ප්‍රධාන පරිපථ පුවරුව කුමක්ද?", listOf("මව්පුවරුව (Motherboard)", "Power Supply", "Heat Sink", "Cooling Fan"), 0, "මව්පුවරුව සියලුම ඉලෙක්ට්‍රොනික සංරචක එකිනෙකට සම්බන්ධ කරන කේන්ද්‍රස්ථානයයි.")
        8 -> QuizQuestion(qNumber, "ප්‍රතිදානය කඩදාසියක ස්පර්ශ කළ හැකි ලෙස මුද්‍රණය කර ලබාදෙන පිටපත කුමක්ද?", listOf("දෘඪ පිටපතක් (Hard Copy)", "මෘදු පිටපතක් (Soft Copy)", "ඩිජිටල් ගොනුවක්", "ඊමේල්"), 0, "මුද්‍රිත කඩදාසිය Hard Copy ලෙසත්, තිරයේ පෙනෙන ගොනුව Soft Copy ලෙසත් හැඳින්වේ.")
        9 -> QuizQuestion(qNumber, "නවීන පරිගණකවල චලනය වන කොටස් රහිතව අතිශය වේගයෙන් දත්ත කියවන නව ගබඩා මාධ්‍යය කුමක්ද?", listOf("SSD (Solid State Drive)", "Floppy Disk", "Magnetic Tape", "CD-ROM"), 0, "SSD ෆ්ලෑෂ් මතක තාක්ෂණය භාවිත කරන බැවින් සාම්ප්‍රදායික HDD වලට වඩා බෙහෙවින් වේගවත්ය.")
        else -> QuizQuestion(qNumber, "CPU හි උපදෙස් ලබාගැනීම, විකේතනය හා පාලනය සිදුකරන කොටස කුමක්ද?", listOf("පාලන ඒකකය (Control Unit - CU)", "ALU", "Monitor", "Bus"), 0, "CU මඟින් පරිගණකයේ සියලු උපාංග අතර දත්ත ගලායාම සම්බන්ධීකරණය කරයි.")
      }
      2 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "ද්විමය (Binary) සංඛ්‍යා පද්ධතියේ පාදය (Base) කීයද?", listOf("2 (සංකේත 0 සහ 1)", "8", "10", "16"), 0, "ද්විමය පද්ධතිය 0 සහ 1 යන සංඛ්‍යාංක දෙක මත පදනම් වේ.")
        2 -> QuizQuestion(qNumber, "දශමය 5 (Denary 5) ද්විමය සංඛ්‍යාවක් ලෙස දැක්වූ විට කුමක්ද?", listOf("101₂", "110₂", "111₂", "100₂"), 0, "4 + 0 + 1 = 5 එනම් 101₂ වේ.")
        3 -> QuizQuestion(qNumber, "ද්විමය 1111₂ ට අනුරූප දශමය සංඛ්‍යාව කීයද?", listOf("15", "14", "16", "8"), 0, "8 + 4 + 2 + 1 = 15.")
        4 -> QuizQuestion(qNumber, "බයිට් (Byte) 1ක් යනු බිට් (Bits) කීයක එකතුවක්ද?", listOf("බිට් 8 කි", "බිට් 4 කි (Nibble)", "බිට් 16 කි", "බිට් 32 කි"), 0, "බිටු 8ක් එකතු වූ විට බයිට් 1ක් සෑදේ.")
        5 -> QuizQuestion(qNumber, "1 කිලෝබයිට් (1 KB) යනු බයිට් කීයකට සමානද?", listOf("බයිට් 1024 කි", "බයිට් 1000 කි", "බයිට් 512 කි", "බයිට් 2048 කි"), 0, "පරිගණක ක්ෂේත්‍රයේ 1 KB = 2¹⁰ = 1024 Bytes වේ.")
        6 -> QuizQuestion(qNumber, "ෂඩ්දශමය (Hexadecimal) සංඛ්‍යා පද්ධතියේ පාදය සහ සංකේත මොනවාද?", listOf("පාදය 16 (0-9 සහ A-F)", "පාදය 8", "පාදය 2", "පාදය 12"), 0, "ෂඩ්දශමයේදී 0-9 දක්වා අංක ද, 10-15 දක්වා A, B, C, D, E, F අකුරු ද යොදාගනී.")
        7 -> QuizQuestion(qNumber, "ASCII කේත ක්‍රමයේදී එක් අක්ෂරයක් නිරූපණය කිරීමට බිට් කීයක් යොදාගනීද?", listOf("බිට් 7 ක් හෝ 8 ක්", "බිට් 2 ක්", "බිට් 16 ක්", "බිට් 32 ක්"), 0, "සම්මත ASCII බිට් 7කින් ද (කේත 128), විස්තෘත ASCII බිට් 8කින් ද ක්‍රියා කරයි.")
        8 -> QuizQuestion(qNumber, "සිංහල, දෙමළ ඇතුළු ලොව සියලු භාෂාවල අක්ෂර ඩිජිටල්ව නිරූපණය කිරීමට යොදන ජාත්‍යන්තර කේත ක්‍රමය කුමක්ද?", listOf("යුනිකෝඩ් (Unicode)", "ASCII", "BCD", "EBCDIC"), 0, "යුනිකෝඩ් ක්‍රමය මඟින් ලොව සියලු අක්ෂර අනන්‍ය සංඛ්‍යාංක කේතයකින් හඳුන්වයි.")
        9 -> QuizQuestion(qNumber, "බිටු 4කින් සමන්විත දත්ත ප්‍රමාණයක් හඳුන්වන විශේෂ නාමය කුමක්ද?", listOf("නිබල් (Nibble)", "බයිට්", "වර්ඩ්", "බ්ලොක්"), 0, "බිට් 4ක් නිබල් 1ක් (Nibble) ලෙස හැඳින්වේ.")
        else -> QuizQuestion(qNumber, "1 මෙගාබයිට් (1 MB) යනු කිලෝබයිට් (KB) කීයක්ද?", listOf("1024 KB", "1000 KB", "1048576 KB", "100 KB"), 0, "1 MB = 1024 KB වේ.")
      }
