        4 -> QuizQuestion(qNumber, "කාබනික ගොවිතැනේදී දියර පොහොරක් ලෙස ගොවීන් පහසුවෙන් සකසා ගන්නා මිශ්‍රණය කුමක්ද?", listOf("ජීවාමෘත හෝ කොම්පෝස්ට් තේ (Jeevamrutha)", "යූරියා ද්‍රාවණය", "කෘමිනාශක", "ලුණු වතුර"), 0, "ගොම, ගව මුත්‍රා, බෙලි ආදිය පැසවීමෙන් ක්ෂුද්‍රජීවී දියර පොහොර සාදා ගනී.")
        5 -> QuizQuestion(qNumber, "කෘමීන් පලවා හැරීම සඳහා බෝග අතර සුදුළූණු, ඉඟුරු, මාරිගෝල්ඩ් (දාස්පෙතියා) වැනි ශාක සිටුවීම කුමක්ද?", listOf("මිත්‍ර ශාක වගාව (Companion Planting)", "ඒක බෝග වගාව", "වල් මර්දනය", "කප්පාදුව"), 0, "දාස්පෙතියා මුල්වලින් නෙමටෝඩාවන් මර්දනය වන අතර සුවඳින් කෘමීන් විකර්ෂණය වේ.")
        6 -> QuizQuestion(qNumber, "කාබනික නිෂ්පාදන සඳහා වෙළඳපොළේ ඉහළ මිලක් ලැබීමට හේතුව කුමක්ද?", listOf("වස විස නැති සෞඛ්‍ය සම්පන්න හා පරිසර හිතකාමී නිෂ්පාදන වීම", "හිඟ වීම පමණක්", "ඇසුරුම් අලංකාර වීම", "රජය නියම කිරීම"), 0, "පාරිභෝගිකයන් තම සෞඛ්‍යය වෙනුවෙන් කාබනික ආහාරවලට වැඩි කැමැත්තක් දක්වයි.")
        7 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ කාබනික නිෂ්පාදන සහතික කිරීම සඳහා ඇති ප්‍රමිතිය කුමක්ද?", listOf("ශ්‍රී ලංකා කාබනික ප්‍රමිතිය (SLS 1324)", "ISO 9001 පමණි", "GMP පමණි", "HACCP"), 0, "SLS 1324 මඟින් නිෂ්පාදනය සැබෑ කාබනික එකක් බව තහවුරු කරයි.")
        8 -> QuizQuestion(qNumber, "වනාන්තරයක ආකෘතිය අනුව විවිධ උසින් යුත් බහු වාර්ෂික ශාක හා බෝග එකට වගා කරන සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", listOf("කඳුකර ගෙවතු වගාව (Kandyan Forest Garden System)", "තේ වත්ත", "රබර් වත්ත", "කුඹුර"), 0, "මහනුවර සම්ප්‍රදායික ගෙවතු ලෝකයේ විශිෂ්ටතම තිරසර කෘෂි පද්ධතියක් ලෙස පිළිගැනේ.")
        9 -> QuizQuestion(qNumber, "පස පෙරළීමෙන් තොරව (No-till farming) බීජ සිටුවීමේ වාසිය කුමක්ද?", listOf("පාංශු ව්‍යුහය ආරක්ෂා වීම හා කාබන් වායුගෝලයට මුදාහැරීම වැළකීම", "වල් පැළ වැඩිවීම", "වියදම වැඩිවීම", "පස නිසරු වීම"), 0, "පස නොපෙරළීමෙන් පාංශු තෙතමනය හා ජීවීන් ආරක්ෂා වේ.")
        else -> QuizQuestion(qNumber, "පාරිසරික සමතුලිතතාව රැකෙන පරිදි ස්වභාවධර්මයේ නීතිවලට අනුකූලව නිර්මාණය කරන තිරසර කෘෂි සැලසුම්කරණය කුමක්ද?", listOf("පර්මාකල්චර් (Permaculture - ස්ථිර කෘෂිකර්මය)", "කාර්මික වගාව", "ඒක බෝග වගාව", "වල් නාශක ගැසීම"), 0, "Permaculture මඟින් මිනිසාට ආහාර මෙන්ම පරිසරයට ආරක්ෂාව සපයයි.")
      }
    }
  }

  // -------------------------------------------------------------
  // ENGLISH (ඉංග්‍රීසි භාෂාව)
  // -------------------------------------------------------------
  fun getEnglishQuestion(grade: String, setIdx: Int, qIdx: Int, qNumber: Int, topic: String): QuizQuestion {
    return when (setIdx) {
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "Choose the correct irregular plural form of the noun 'Child':", listOf("Children", "Childs", "Childes", "Childrens"), 0, "'Child' has the irregular plural form 'children'.")
        2 -> QuizQuestion(qNumber, "Which of the following is an uncountable noun?", listOf("Water", "Book", "Pen", "Apple"), 0, "Liquids like water, milk, and oil cannot be counted individually.")
        3 -> QuizQuestion(qNumber, "Identify the collective noun in the sentence: 'A flock of birds flew across the sky.'", listOf("flock", "birds", "flew", "sky"), 0, "'Flock' refers to a group of birds together.")
        4 -> QuizQuestion(qNumber, "Choose the correct pronoun: 'Kamal is my friend. ___ lives in Kandy.'", listOf("He", "She", "They", "It"), 0, "Male singular subject takes the personal pronoun 'He'.")
        5 -> QuizQuestion(qNumber, "Which word is an abstract noun denoting a quality or feeling?", listOf("Honesty", "Table", "Dog", "City"), 0, "'Honesty' is an intangible quality that cannot be physically touched.")
        6 -> QuizQuestion(qNumber, "Choose the correct plural form of 'Knife':", listOf("Knives", "Knifes", "Knifess", "Knivs"), 0, "Nouns ending in '-fe' usually change to '-ves' (knife -> knives).")
        7 -> QuizQuestion(qNumber, "Identify the possessive pronoun: 'This umbrella is not mine, it is ___.'", listOf("hers", "her", "she", "him"), 0, "'Hers' is an independent possessive pronoun.")
        8 -> QuizQuestion(qNumber, "Choose the correct plural form of 'Tooth':", listOf("Teeth", "Tooths", "Teethes", "Toothies"), 0, "'Tooth' changes internal vowels to form irregular plural 'teeth'.")
        9 -> QuizQuestion(qNumber, "Which word in the sentence is an adjective? 'The little girl wore a pretty dress.'", listOf("little and pretty", "girl", "wore", "dress"), 0, "'Little' and 'pretty' describe nouns, so they are adjectives.")
        else -> QuizQuestion(qNumber, "Select the correct plural of 'Mouse':", listOf("Mice", "Mouses", "Micees", "Mousen"), 0, "The irregular plural form of 'mouse' is 'mice'.")
      }
      2 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "Identify the correct verb tense: 'She visits her grandmother every Sunday.'", listOf("Simple Present Tense", "Present Continuous", "Simple Past", "Future Simple"), 0, "Habitual routines take the Simple Present tense.")
        2 -> QuizQuestion(qNumber, "'They ___ football in the ground right now.' Fill in the blank:", listOf("are playing", "is playing", "played", "will play"), 0, "Action happening 'right now' with plural 'they' takes 'are playing'.")
        3 -> QuizQuestion(qNumber, "What is the past simple tense form of the irregular verb 'Go'?", listOf("Went", "Goed", "Gone", "Going"), 0, "The principal parts are go -> went -> gone.")
        4 -> QuizQuestion(qNumber, "'Yesterday, we ___ a very interesting English movie.'", listOf("watched", "watch", "watches", "are watching"), 0, "'Yesterday' indicates a completed past event, so 'watched' is correct.")
        5 -> QuizQuestion(qNumber, "Choose the correct sentence in Future Simple tense:", listOf("I will help you with your homework tomorrow.", "I helped you yesterday.", "I am helping you now.", "I helps you."), 0, "'Will + base verb' indicates future promises or predictions.")
        6 -> QuizQuestion(qNumber, "Choose the correct form: 'The sun ___ in the east.'", listOf("rises", "rise", "is rising", "rose"), 0, "Universal scientific truths take simple present singular verb 'rises'.")
        7 -> QuizQuestion(qNumber, "'While I was reading a book, the telephone ___.'", listOf("rang", "rings", "was ringing", "rung"), 0, "A shorter interrupting action in the past takes Simple Past ('rang').")
        8 -> QuizQuestion(qNumber, "Which sentence expresses Present Perfect tense correctly?", listOf("She has finished her homework.", "She finished her homework.", "She is finish.", "She will finish."), 0, "'Has/Have + past participle (V3)' forms Present Perfect.")
        9 -> QuizQuestion(qNumber, "Identify the past participle (V3) of the verb 'Eat':", listOf("Eaten", "Ate", "Eating", "Eats"), 0, "Eat (V1) -> Ate (V2) -> Eaten (V3).")
        else -> QuizQuestion(qNumber, "'He ___ in this school since 2018.'", listOf("has been studying", "is studying", "studied", "studies"), 0, "'Since 2018' indicates an action continuing from the past, taking Present Perfect Continuous.")
      }
      3 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "Change to Passive Voice: 'The cat chased the mouse.'", listOf("The mouse was chased by the cat.", "The mouse is chased by the cat.", "The cat was chased by the mouse.", "The mouse chases the cat."), 0, "Past simple passive: object + was/were + V3 + by subject.")
        2 -> QuizQuestion(qNumber, "Active Voice: 'Kamal wrote a letter.' What is the passive form?", listOf("A letter was written by Kamal.", "A letter is written by Kamal.", "Kamal was written a letter.", "A letter wrote Kamal."), 0, "'Wrote' changes to 'was written by'.")
        3 -> QuizQuestion(qNumber, "Change to Passive: 'The chef is cooking delicious food.'", listOf("Delicious food is being cooked by the chef.", "Delicious food was cooked.", "Delicious food has cooked.", "Food cooks chef."), 0, "Present continuous passive takes 'is/are being + V3'.")
        4 -> QuizQuestion(qNumber, "Passive Voice: 'The homework has been completed by Nimal.' What is the active voice?", listOf("Nimal has completed the homework.", "Nimal completed homework.", "Nimal is completing homework.", "Nimal will complete."), 0, "Present perfect passive transforms back to 'has + V3'.")
        5 -> QuizQuestion(qNumber, "Change to Passive: 'They will announce the exam results tomorrow.'", listOf("The exam results will be announced tomorrow.", "The exam results will announce.", "Results are announced.", "Results announced."), 0, "Future passive takes 'will be + V3'.")
        6 -> QuizQuestion(qNumber, "'English ___ all over the world.' (speak)", listOf("is spoken", "speaks", "was spoke", "speaking"), 0, "General fact in passive: 'is spoken'.")
        7 -> QuizQuestion(qNumber, "Which of the following sentences is in the Passive Voice?", listOf("The robber was arrested by the police.", "The police arrested the robber.", "The police will arrest him.", "Robber escaped."), 0, "Subject receives the action ('was arrested by').")
        8 -> QuizQuestion(qNumber, "Change into Passive: 'Clean your room!' (Imperative)", listOf("Let your room be cleaned.", "Room clean you.", "You cleaned room.", "Cleaned room."), 0, "Imperative passive starts with 'Let + object + be + V3'.")
        9 -> QuizQuestion(qNumber, "Change to Active: 'A song was sung by Sunimal.'", listOf("Sunimal sang a song.", "Sunimal sings a song.", "Sunimal is singing.", "Sunimal has sung."), 0, "'Was sung' converts back to past tense 'sang'.")
        else -> QuizQuestion(qNumber, "Why do we use passive voice in formal exam essays and scientific reports?", listOf("To focus on the action/result rather than who performed it.", "Because active voice is wrong.", "To make sentences shorter.", "It is easier."), 0, "Passive voice emphasizes the process and result objectively.")
      }
      4 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "Change to Indirect Speech: He said, 'I am very tired.'", listOf("He said that he was very tired.", "He said that I am tired.", "He says he is tired.", "He said he will be tired."), 0, "Present tense 'am' shifts to past tense 'was' in reported speech.")
        2 -> QuizQuestion(qNumber, "Nimal said, 'I have bought a new bicycle.'", listOf("Nimal said that he had bought a new bicycle.", "Nimal said he bought a bicycle.", "Nimal says he has bought.", "Nimal said he buy."), 0, "Present perfect 'have bought' changes to Past Perfect 'had bought'.")
        3 -> QuizQuestion(qNumber, "The teacher said to the boys, 'Do not make a noise.'", listOf("The teacher ordered the boys not to make a noise.", "The teacher said don't make noise.", "The teacher asked to make noise.", "Teacher told no noise."), 0, "Negative imperative changes to 'not to + verb'.")
        4 -> QuizQuestion(qNumber, "She said, 'Where do you live?'", listOf("She asked me where I lived.", "She asked where do I live.", "She asked if I lived.", "She said where I live."), 0, "Wh-questions keep the question word with normal assertive word order.")
        5 -> QuizQuestion(qNumber, "Kamal asked me, 'Are you coming to the party tonight?'", listOf("Kamal asked me if I was coming to the party that night.", "Kamal asked are you coming.", "Kamal asked that I come.", "Kamal asked tonight."), 0, "Yes/No questions use 'if' or 'whether', and 'tonight' changes to 'that night'.")
        6 -> QuizQuestion(qNumber, "In indirect speech, the time adverb 'today' changes to:", listOf("that day", "yesterday", "tomorrow", "this day"), 0, "'Today' changes to 'that day' in reported speech.")
        7 -> QuizQuestion(qNumber, "In indirect speech, 'tomorrow' changes to:", listOf("the following day / the next day", "yesterday", "the day before", "today"), 0, "'Tomorrow' becomes 'the next day' or 'the following day'.")
        8 -> QuizQuestion(qNumber, "She said, 'I will call you tomorrow.'", listOf("She said that she would call me the next day.", "She said she will call me.", "She said she called.", "She said she would call tomorrow."), 0, "'Will' changes to 'would', and 'tomorrow' to 'the next day'.")
        9 -> QuizQuestion(qNumber, "The doctor said to the patient, 'Take this medicine twice a day.'", listOf("The doctor advised the patient to take that medicine twice a day.", "Doctor said take medicine.", "Doctor told that take medicine.", "Doctor asked medicine."), 0, "Medical instructions are reported using 'advised + to + verb'.")
        else -> QuizQuestion(qNumber, "In indirect speech, 'here' usually changes to:", listOf("there", "everywhere", "nowhere", "near"), 0, "'Here' denotes distance in indirect speech and changes to 'there'.")
      }
      5 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "Choose the correct preposition: 'She has been waiting for the bus ___ 8 o'clock.'", listOf("since", "for", "from", "at"), 0, "'Since' is used with a specific starting point in time.")
        2 -> QuizQuestion(qNumber, "'He has lived in Colombo ___ five years.'", listOf("for", "since", "during", "in"), 0, "'For' denotes a duration or period of time (five years).")
        3 -> QuizQuestion(qNumber, "Choose the correct preposition: 'He is very good ___ mathematics.'", listOf("at", "in", "on", "with"), 0, "We say 'good at' an academic subject or skill.")
        4 -> QuizQuestion(qNumber, "'The train arrived ___ the station on time.'", listOf("at", "in", "on", "to"), 0, "Specific arrival points take the preposition 'at'.")
        5 -> QuizQuestion(qNumber, "Choose the correct conjunction: 'He studied hard, ___ he failed the exam.'", listOf("but", "and", "so", "because"), 0, "'But' introduces a contrast between hard work and failure.")
        6 -> QuizQuestion(qNumber, "'She stayed at home ___ it was raining heavily.'", listOf("because", "although", "so", "but"), 0, "'Because' introduces the reason for staying home.")
        7 -> QuizQuestion(qNumber, "Choose the correct article: 'Sri Lanka is ___ island in the Indian Ocean.'", listOf("an", "a", "the", "no article"), 0, "'Island' starts with a vowel sound, so indefinite article 'an' is used.")
        8 -> QuizQuestion(qNumber, "'___ Mount Everest is the highest mountain peak in the world.'", listOf("No article", "The", "A", "An"), 0, "Individual mountain peaks do not take the definite article 'the'.")
        9 -> QuizQuestion(qNumber, "Choose the correct preposition: 'The cat jumped ___ the wall.'", listOf("over", "under", "in", "at"), 0, "Motion across and above an obstacle takes 'over'.")
        else -> QuizQuestion(qNumber, "'Neither Kamal ___ Nimal attended the meeting.'", listOf("nor", "or", "and", "also"), 0, "Correlative conjunction pair: 'Neither ... nor'.")
      }
      6 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "What is the synonym (word with similar meaning) of 'Abundant'?", listOf("Plentiful", "Scarce", "Few", "Empty"), 0, "'Abundant' means existing in large quantities (plentiful).")
        2 -> QuizQuestion(qNumber, "What is the antonym (opposite word) of 'Courageous'?", listOf("Cowardly", "Brave", "Fearless", "Heroic"), 0, "'Courageous' means brave; its opposite is 'cowardly'.")
        3 -> QuizQuestion(qNumber, "Choose the word with the correct spelling:", listOf("Necessary", "Neccessary", "Necesary", "Necassary"), 0, "Correct spelling is N-E-C-E-S-S-A-R-Y (one c, two s's).")
        4 -> QuizQuestion(qNumber, "Choose the correct prefix to form the opposite of 'Polite':", listOf("im- (Impolite)", "un-", "dis-", "in-"), 0, "The prefix 'im-' is attached before 'polite' to mean rude.")
        5 -> QuizQuestion(qNumber, "Choose the correct suffix to turn the verb 'Teach' into a person:", listOf("-er (Teacher)", "-or", "-ist", "-ian"), 0, "Adding '-er' forms the noun agent 'teacher'.")
        6 -> QuizQuestion(qNumber, "What is the meaning of the idiom 'A piece of cake'?", listOf("Something very easy to do", "A delicious dessert", "A difficult challenge", "A birthday gift"), 0, "The idiom means an easy task or test.")
        7 -> QuizQuestion(qNumber, "Choose the correct spelling:", listOf("Environment", "Enviroment", "Environmant", "Envirament"), 0, "Correct spelling is E-N-V-I-R-O-N-M-E-N-T.")
        8 -> QuizQuestion(qNumber, "What is the antonym of 'Permanent'?", listOf("Temporary", "Durable", "Constant", "Eternal"), 0, "'Permanent' lasts forever; 'temporary' lasts only a short time.")
        9 -> QuizQuestion(qNumber, "A person who writes poems is called a:", listOf("Poet", "Author", "Novelist", "Playwright"), 0, "A writer of poetry is a poet.")
        else -> QuizQuestion(qNumber, "Choose the correct synonym of 'Huge':", listOf("Enormous / Gigantic", "Tiny", "Small", "Miniature"), 0, "'Huge' means very large (enormous).")
      }
      7 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "What is the standard opening salutation in a formal business letter?", listOf("Dear Sir / Madam,", "Hi buddy,", "Dearest friend,", "Hello there,"), 0, "Formal letters begin with 'Dear Sir / Madam,' or the recipient's title.")
        2 -> QuizQuestion(qNumber, "Which complimentary close is most appropriate for a formal letter starting with 'Dear Sir'?", listOf("Yours faithfully,", "With love,", "Cheers,", "Yours warmly,"), 0, "When recipient name is unknown, use 'Yours faithfully,'. When named, use 'Yours sincerely,'.")
        3 -> QuizQuestion(qNumber, "Where should the sender's address and date be placed in a formal letter?", listOf("Top right corner (or top left in modern block format)", "Bottom right", "In the middle", "Inside envelope only"), 0, "Sender's address and date appear at the top before recipient address.")
        4 -> QuizQuestion(qNumber, "What is the purpose of the 'Subject' line in a formal letter?", listOf("To state the main reason of the letter clearly and concisely.", "To say hello", "To sign name", "To write date"), 0, "A concise subject line helps the reader immediately understand the purpose.")
        5 -> QuizQuestion(qNumber, "Which of the following phrases is suitable for an informal letter to a friend?", listOf("I was so thrilled to hear your great news!", "I am writing to officially apply for...", "Yours faithfully,", "Please find enclosed herewith"), 0, "Friendly, conversational language is used for informal correspondence.")
        6 -> QuizQuestion(qNumber, "What should be included at the very end of a formal letter after your complimentary close?", listOf("Your signature followed by your full name in print", "Only your nickname", "A drawing", "Nothing"), 0, "A formal letter concludes with signature and printed full name.")
        7 -> QuizQuestion(qNumber, "In which letter would you write: 'I would be grateful if you could grant me three days leave'?", listOf("Formal letter to a school principal or employer", "Friendly postcard", "Birthday card", "Email to cousin"), 0, "Polite, respectful phrasing is standard for official requests.")
        8 -> QuizQuestion(qNumber, "Which abbreviation stands for 'Postscript' added at the bottom of a friendly letter?", listOf("P.S.", "E.g.", "I.e.", "Etc."), 0, "'P.S.' (postscript) adds an afterthought at the end of a letter.")
        9 -> QuizQuestion(qNumber, "When writing to a friend, what is an appropriate sign-off?", listOf("Your loving friend,", "Yours faithfully,", "Respectfully yours,", "To whom it may concern,"), 0, "'Your loving friend,' or 'Warm regards,' is suitable for friends.")
        else -> QuizQuestion(qNumber, "Why should contractions like 'don't' or 'gonna' be avoided in formal letters?", listOf("Formal letters require standard, uncontracted grammatical English.", "They are misspelled words.", "They take more space.", "No reason."), 0, "Full forms ('do not', 'cannot') maintain professional tone.")
      }
      8 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "What is the primary purpose of a school Notice on a bulletin board?", listOf("To inform students and teachers about an upcoming event or announcement.", "To write essays", "To tell jokes", "To practice handwriting"), 0, "Notices communicate factual information publicly and clearly.")
        2 -> QuizQuestion(qNumber, "Which four essential details must always be present in an event notice?", listOf("Event name, Date, Time, and Venue (place)", "Price and pictures only", "Organizers' birth dates", "Weather forecast"), 0, "Readers need to know what, when, what time, and where.")
        3 -> QuizQuestion(qNumber, "What does the word 'Venue' mean in an official notice?", listOf("The place where the event will take place", "The date", "The ticket price", "The chief guest"), 0, "'Venue' refers to the location (e.g. School Main Hall).")
        4 -> QuizQuestion(qNumber, "How should the heading of a Notice be written to attract immediate attention?", listOf("In clear, bold, centered capital letters", "Very tiny in a corner", "In pencil", "Hidden at bottom"), 0, "A prominent heading ensures people notice and read the announcement.")
        5 -> QuizQuestion(qNumber, "Who should sign or issue a notice for it to be valid?", listOf("The authorized official (e.g. Secretary / Principal)", "Any student anonymously", "No one", "A visitor"), 0, "The designation and signature of the issuing authority gives authenticity.")
        6 -> QuizQuestion(qNumber, "In a telephone message note, why is the 'Time of Call' recorded?", listOf("So the recipient knows when the message arrived and how urgent it is.", "To check the clock", "For entertainment", "No reason"), 0, "Timing helps prioritize callback and follow-up actions.")
        7 -> QuizQuestion(qNumber, "What tone of language should be maintained in a public notice?", listOf("Formal, clear, direct and polite", "Slang and casual", "Poetic and rhyming", "Angry and demanding"), 0, "Clear, concise, and courteous language prevents misunderstandings.")
        8 -> QuizQuestion(qNumber, "Which phrase is common in a school notice?", listOf("'All members of the English Club are requested to attend...'", "'Hey guys come over...'", "'You must do it now!'", "'I don't care...'"), 0, "Courteous requests maintain discipline and professionalism.")
        9 -> QuizQuestion(qNumber, "Where is a circular typically distributed?", listOf("Among members of an organization, staff, or club", "On street walls", "In newspapers only", "On radio only"), 0, "Circulars distribute specific internal instructions to a designated group.")
        else -> QuizQuestion(qNumber, "Why should a notice be enclosed in an outlined box?", listOf("To give it a neat, structured, and visually prominent presentation.", "To save paper", "To hide text", "No reason"), 0, "Boxing a notice is a standard exam presentation rule.")
      }
      9 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "What is a Bar Chart used for in data presentation?", listOf("To compare different categories of data using vertical or horizontal rectangular bars.", "To write stories", "To calculate logarithms", "To draw pictures"), 0, "Bar charts display category quantities for easy comparison.")
        2 -> QuizQuestion(qNumber, "What does a Pie Chart represent?", listOf("A whole circle divided into proportional slices representing percentage parts of a 100% total.", "A line graph", "A food recipe", "A bar chart"), 0, "Pie charts show proportions of a whole (100% / 360°).")
        3 -> QuizQuestion(qNumber, "When describing an upward trend in a graph, which verb can you use?", listOf("Increased / Rose / Climbed", "Decreased", "Dropped", "Fell"), 0, "Increase, rise, and climb describe upward movements.")
        4 -> QuizQuestion(qNumber, "When a number in a graph reaches its highest point, it has reached its:", listOf("Peak (Highest point)", "Lowest level", "Average", "Origin"), 0, "'Peaked at' means reached the maximum value.")
        5 -> QuizQuestion(qNumber, "Which word describes a line that does not change over time?", listOf("Remained steady / constant", "Fluctuated widely", "Plummeted", "Rocketed"), 0, "'Remained constant' means flat, stable performance.")
        6 -> QuizQuestion(qNumber, "What is the first introductory sentence of a graph description essay?", listOf("State what the chart shows, including the title and time period.", "Give your personal opinion", "State the conclusion", "List all numbers"), 0, "e.g., 'This bar chart illustrates the preferred sports of Grade 10 students.'")
        7 -> QuizQuestion(qNumber, "Which phrase describes a sudden, sharp decline in data?", listOf("Dropped sharply / plummeted", "Increased gradually", "Stood at", "Leveled off"), 0, "'Plummeted' or 'dropped sharply' indicates a steep fall.")
        8 -> QuizQuestion(qNumber, "What word represents 'more than half' of a surveyed population?", listOf("The majority (more than 50%)", "The minority", "A tiny fraction", "Zero"), 0, "'Majority' signifies the greatest part of a whole.")
        9 -> QuizQuestion(qNumber, "What linking phrase can compare two contrasting categories in a chart?", listOf("While / In contrast / On the other hand", "Because of", "Therefore", "In addition"), 0, "Contrast connectives highlight differences clearly.")
        else -> QuizQuestion(qNumber, "What should be written in the concluding sentence of a chart interpretation?", listOf("A brief summary of the main trend or overall finding.", "Repeat every number again", "Give your home address", "Say goodbye"), 0, "A concise overview wraps up the analysis effectively.")
      }
      else -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "What is the topic sentence of a paragraph?", listOf("The sentence that expresses the main idea of the paragraph.", "The last sentence", "The shortest sentence", "A quotation"), 0, "The topic sentence introduces the core subject of the paragraph.")
        2 -> QuizQuestion(qNumber, "What are supporting sentences in an essay paragraph?", listOf("Sentences that provide facts, examples, and details explaining the topic sentence.", "Random sentences", "Sentences copied from dictionary", "Headings"), 0, "Supporting details elaborate and justify the central idea.")
        3 -> QuizQuestion(qNumber, "Which linking word adds extra supporting information in an essay?", listOf("Furthermore / In addition / Moreover", "However", "Although", "In contrast"), 0, "'Furthermore' and 'Moreover' add progressive supporting points.")
        4 -> QuizQuestion(qNumber, "Which cohesive device introduces a concluding thought in an essay?", listOf("In conclusion / To sum up", "First of all", "For instance", "Suddenly"), 0, "'In conclusion' signals the final synthesis of the essay.")
        5 -> QuizQuestion(qNumber, "What is the ideal minimum structure for a standard G.C.E. O/L essay?", listOf("Introduction, 2-3 body paragraphs, and a Conclusion", "One giant single paragraph", "Only bullet points", "Two sentences"), 0, "Clear paragraph division ensures organization and coherence.")
        6 -> QuizQuestion(qNumber, "Why should you avoid repeating the same word multiple times in an essay?", listOf("Using rich synonyms demonstrates vocabulary range and improves readability.", "It is illegal", "It wastes ink", "Computers reject it"), 0, "Variety in vocabulary showcases strong language proficiency.")
        7 -> QuizQuestion(qNumber, "Which punctuation mark is used to separate items in a list?", listOf("Comma (,)", "Full stop (.)", "Question mark (?)", "Exclamation mark (!)"), 0, "Commas separate serial items (e.g. apples, oranges, and bananas).")
        8 -> QuizQuestion(qNumber, "Which sentence has correct punctuation and capitalization?", listOf("My brother lives in London, which is the capital of the UK.", "my brother lives in london.", "My Brother lives In London.", "my brother, lives in uk"), 0, "Proper nouns (London, UK) and sentence beginnings must be capitalized.")
        9 -> QuizQuestion(qNumber, "What should you do during the last 5 minutes of an English exam paper?", listOf("Proofread carefully for spelling, tense consistency, and punctuation errors.", "Put head down", "Erase everything", "Hand over paper early"), 0, "Careful proofreading catches preventable grammatical and spelling slips.")
        else -> QuizQuestion(qNumber, "Which transition word shows a cause-and-effect relationship?", listOf("Consequently / Therefore / As a result", "Meanwhile", "Similarly", "Unlike"), 0, "'Therefore' and 'Consequently' demonstrate logical results.")
      }
    }
  }

  // -------------------------------------------------------------
  // ELECTIVES & GENERAL SUBJECTS (Civic, Music, Art, Dance, Drama)
  // -------------------------------------------------------------
  fun getElectiveQuestion(norm: String, grade: String, subjectName: String, setIdx: Int, qIdx: Int, qNumber: Int, topic: String): QuizQuestion {
    return when (norm) {
      "civic" -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයක පරමාධිපත්‍ය බලය හිමිවන්නේ කාටද?", listOf("මහජනතාවට (People)", "රජුට පමණි", "හමුදාවට", "පොලිසියට"), 0, "ප්‍රජාතන්ත්‍රවාදයේදී ආණ්ඩු බලය ජනතාව සතු වන අතර ඡන්දයෙන් නියෝජිතයන් පත්කර ගනී.")
        2 -> QuizQuestion(qNumber, "ශ්‍රී ලංකා ප්‍රජාතාන්ත්‍රික සමාජවාදී ජනරජයේ ආණ්ඩුක්‍රමයේ ප්‍රධාන කුලුනු 3 මොනවාද?", listOf("ව්‍යවස්ථාදායකය, විධායකය, අධිකරණය", "පාසල, පන්සල, රෝහල", "හමුදාව, නාවික, ගුවන්", "රාජ්‍ය, පුද්ගලික, සමූපකාර"), 0, "නීති හැදීම (පාර්ලිමේන්තුව), ක්‍රියාත්මක කිරීම (ජනාධිපති/ඇමති මණ්ඩලය) හා සාධාරණත්වය රැකීම (අධිකරණය) තුලනය වේ.")
        3 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ ව්‍යවස්ථාදායක බලය ක්‍රියාත්මක කරන උත්තරීතර මණ්ඩලය කුමක්ද?", listOf("පාර්ලිමේන්තුව (Parliament - මන්ත්‍රීවරු 225)", "ශ්‍රේෂ්ඨාධිකරණය", "නගර සභාව", "පොලිසිය"), 0, "පාර්ලිමේන්තුව රටේ නීති සම්පාදනය සහ රාජ්‍ය මූල්‍ය පාලනය සිදුකරයි.")
        4 -> QuizQuestion(qNumber, "එක්සත් ජාතීන්ගේ සංවිධානය (UN) විසින් මානව හිමිකම් පිළිබඳ විශ්ව ප්‍රකාශනය සම්මත කළේ කවදාද?", listOf("1948 දෙසැම්බර් 10 වන දින", "1945 ඔක්තෝබර් 24", "1972 මැයි 22", "1950 ජනවාරි 1"), 0, "මානව හිමිකම් දිනය සෑම වසරකම දෙසැම්බර් 10 දින සමරනු ලැබේ.")
        5 -> QuizQuestion(qNumber, "යහපත් පුරවැසියෙකු සතුවිය යුතු අත්‍යවශ්‍ය ලක්ෂණයක් කුමක්ද?", listOf("නීතියට ගරු කිරීම සහ සමාජ වගකීම් නොපිරිහෙළා ඉටුකිරීම", "බදු නොගෙවා සිටීම", "පොදු දේපළ විනාශ කිරීම", "අන්‍යයන් නොසලකා හැරීම"), 0, "අයිතිවාසිකම් මෙන්ම යුතුකම් හා නීතිගරුක බව යහපත් පුරවැසිකමයි.")
        6 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ පළාත් පාලන ආයතන වර්ග 3 මොනවාද?", listOf("මහා නගර සභා, නගර සභා, ප්‍රාදේශීය සභා", "පාර්ලිමේන්තුව, අමාත්‍යාංශ, දෙපාර්තමේන්තු", "පළාත් සභා පමණි", "ගම් සභා"), 0, "පළාත් පාලන ආයතන මඟින් ප්‍රදේශයේ ජනතාවගේ සෞඛ්‍යය, මහාමාර්ග හා පහසුකම් සලසයි.")
        7 -> QuizQuestion(qNumber, "අධිකරණයේ ස්වාධීනත්වය (Independence of the Judiciary) ප්‍රජාතන්ත්‍රවාදයට වැදගත් වන්නේ ඇයි?", listOf("දේශපාලන බලපෑම්වලින් තොරව සැමට සාධාරණ නඩු තීන්දු ලබාදීමට", "නඩු පමා කිරීමට", "දඬුවම් වැඩි කිරීමට", "මුදල් ඉපැයීමට"), 0, "ස්වාධීන අධිකරණයක් මඟින් නීතියේ ආධිපත්‍යය ආරක්ෂා වේ.")
        8 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ උත්තරීතරම අධිකරණය වන්නේ කුමක්ද?", listOf("ශ්‍රේෂ්ඨාධිකරණය (Supreme Court)", "අභියාචනාධිකරණය", "මහාධිකරණය", "දිසා අධිකරණය"), 0, "ආණ්ඩුක්‍රම ව්‍යවස්ථාව අර්ථකථනය කිරීමේ හා මූලික අයිතිවාසිකම් විභාග කිරීමේ බලය ශ්‍රේෂ්ඨාධිකරණය සතුය.")
